final class Engineer { long id; String name; double salary; String project; }
static final String SELECT = "SELECT id, name, salary, project FROM engineers WHERE id = ?";
Engineer find(long id) throws SQLException {
    try (PreparedStatement ps = conn.prepareStatement(SELECT)) {
        ps.setLong(1, id);
        try (ResultSet rs = ps.executeQuery()) { return rs.next() ? mapEngineer(rs) : null; }
